// Synthetic test adapter for the unmerged R223 module; never loaded by Studio.
export function mountBeatMap(container, initial){
 const testStyle=":where(.r226-cut) .tl2-songs{position:relative;height:20px}\n:where(.r226-cut) .tl2-songs .sn{position:absolute;top:3px;font:11px var(--f-tx);color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding-left:0}\n:where(.r226-cut) .tl2-songs .swap{position:absolute;top:1px;height:17px;transform:translateX(-50%);border:1px solid var(--ac);border-radius:9px;background:var(--ac-bg);color:var(--ac-soft);font:10.5px var(--f-tx);padding:0 7px;z-index:2;white-space:nowrap}\n:where(.r226-cut) .tl2-songs .swap[aria-current=\"true\"]{background:var(--ac);color:var(--bg)}\n:where(.r226-cut) .tl2-music{position:relative;height:22px}\n:where(.r226-cut) .tl2-music .seg{position:absolute;top:5px;height:8px;border-radius:2px;background:var(--sec-quiet)}\n:where(.r226-cut) .tl2-music .seg.b{background:var(--sec-build)}\n:where(.r226-cut) .tl2-music .seg.p{background:var(--sec-peak)}\n:where(.r226-cut) .tl2-music .db{position:absolute;top:16px;width:1px;height:5px;background:var(--rule-2)}\n:where(.r226-cut) .tl2-music .fade{position:absolute;top:5px;height:8px;background:linear-gradient(90deg,var(--sec-quiet),transparent)}\n:where(.r226-cut) .tl2-swapline{position:absolute;top:18px;height:42px;width:2px;margin-left:-1px;background:var(--ac);pointer-events:none}\n:where(.r226-cut) .tl2-cut{position:absolute;top:60px;height:76px;width:1px;background:#ffffff14;pointer-events:none}\n:where(.r226-cut) .tl2-cut.hl{background:var(--fam-cut);width:2px;margin-left:-1px}";
 let options={...initial};
 const pct=t=>100*t/options.duration;
 function paint(){container.r226BeatOptions=options;container.innerHTML=`<div class="tl2-songs">${options.songs.map((s,i)=>`<span class="sn" data-design-data style="left:calc(${pct(s.start)}% + ${i?24:4}px);width:max(0px,calc(${pct(s.end-s.start)}% - ${(i?24:4)+(i<options.songs.length-1?24:4)}px))">${s.title}</span>${i?`<button class="bm-swap swap" data-swap="${i}" style="left:${pct(s.start)}%" aria-pressed="${options.selectedSwap===i}">换歌</button>`:''}`).join('')}</div><div class="tl2-music">${options.songs.flatMap(s=>(s.beatMap?.sections||[]).map(section=>{const a=Math.max(s.start,section.start-s.offset+s.start),b=Math.min(s.end,section.end-s.offset+s.start);return b>a?`<i class="seg ${section.kind==='build'?'b':section.kind==='peak'?'p':''}" style="left:${pct(a)}%;width:${pct(b-a)}%"></i>`:'';})).join('')}</div>${options.cuts.map(c=>`<i class="tl2-cut ${c.selected?'hl':''}" style="left:${pct(c.t)}%;top:42px"></i>`).join('')}`;
  const style=document.createElement('style');style.textContent=testStyle;container.append(style);
  container.querySelectorAll('[data-swap]').forEach(b=>b.onclick=e=>{e.stopPropagation();options.onSwapClick?.(+b.dataset.swap);});container.onclick=e=>{if(e.target.closest('[data-swap]'))return;const r=container.getBoundingClientRect();options.onSeek?.((e.clientX-r.left)/r.width*options.duration);};}
 paint();return {update(partial){options={...options,...partial};paint();},setTime(t){container.dataset.time=t;},destroy(){container.innerHTML='';container.onclick=null;}};
}
